import React from "react";
import { useState, useEffect, useRef } from "react";
import { toast } from "react-toastify";
import { useForm } from "react-hook-form";
import api from "../api/Webcall";
import { generateUUID, compressBase64, decompressBase64, } from "../utilities/utils";
import { GetElementList } from "../utilities/getelementlist";
import { GetTaskElements } from "../utilities/getTaskElements";
import appsettings from "../../appsettings.json";

const apiendpoints = appsettings.ApiEndpoints;

function TaskElements({ ScrId }) {

  const [elementList, setElementList] = useState([]);
  const [selectedElementList, setSelectedElementList] = useState([]);
  const { register, getValues, setValue } = useForm({});

  const FetchElementList = async (ScrId, StgId) => {
    const ElementLis = await GetElementList(ScrId, StgId);
    setElementList(ElementLis.body.elements);
  };

  const FetchTskElementList = async (ScrId) => {
    const TskElmList = await GetTaskElements(ScrId);
    setSelectedElementList(TskElmList.body.tskcols);
  };

  useEffect(() => { 
    FetchElementList(ScrId); 
    FetchTskElementList(ScrId);
  }, []);

  const callServer = async (frmData, tag, endPoint) =>{

    const frmHdr = { convid: generateUUID(), tag: tag, orgid: "", vendid: "0", };

    const reqHdr = { };
    const reqdata = { hdr: frmHdr, body: frmData };

    try {
      const response = await api.post( endPoint, compressBase64(reqdata), reqHdr );
      const resData  = JSON.parse(decompressBase64(response.data));

      if (resData.hdr.rst == "SUCCESS")
      {
        setTimeout(() => {
          toast.success("Successfully updated");
          FetchElementList(ScrId);
        }, 300);
      }
      else {
        setTimeout(() => {
          toast.error(JSON.stringify(resData.fdr[0].rstmsg));
        }, 300);
      }

    } catch (err) {
      setTimeout(() => {
        toast.error("Unable to process request");
      }, 300);
    }

  };


  const UIElmList = ({ elmList }) => {

    let elmIds = new Array();
    let nCnt = -1;
    let sElements = selectedElementList;

    const onChangeSelect = (e, ElementId) => {

      if (e.target.checked) {
        let selm = sElements.find(x => x.ElmId == ElementId);
        if (!selm) {
          selm = {};
          selm["ElmId"] = ElementId;
          selm["Hdr"] = "";
          selm["Ord"] = "";
          sElements.push(selm);
          setSelectedElementList(sElements);
        }
      }
      else {
        let selm = sElements.find(x => x.ElmId == ElementId);
        if (selm) {
          let indx = sElements.indexOf(selm);
          sElements.splice(indx, 1);
          setSelectedElementList(sElements);
        }
      }
    }

    return (
      <>
        { (elmList.length > 0) ? elmList.map((data, index) => {
          if (data.ParentElmName == null &&
            (data.DataTypeId == 2 || data.DataTypeId == 3 || data.DataTypeId == 4 ||
              data.DataTypeId == 5 || data.DataTypeId == 6 || data.DataTypeId == 7)) {

            ++nCnt;
            elmIds[nCnt] = data.ElementId;

          
            return (
              <tr key={index}>
                <td>
                  <input {...register('S_' + elmIds[nCnt])} type="checkbox"
                   onClick={(e) => onChangeSelect(e, data.ElementId)} />
                </td>
                <td style={{ fontSize: "15px" }} >{data.ElmName}</td>
                <td><input {...register('HDR_' + elmIds[nCnt])} type="text" /></td>
                <td><input {...register('ORD_' + elmIds[nCnt])} type="number" /></td>
              </tr>
            )

            

          }
        }) : <></>}

        {sElements.map((data) => {
          setValue('S_' + data.ElmId, true);
          setValue('HDR_' + data.ElmId, data.Hdr);
          setValue('ORD_' + data.ElmId, data.Ord);
        }) }

      </>
    )

  };

   
  const resetFormData = () => {

    setSelectedElementList([]);

    elementList.map((elm) => {
      setValue('S_' + elm.ElementId, false);
      setValue('HDR_' + elm.ElementId, '');
      setValue('ORD_' + elm.ElementId, '');
    });
   
  };

  
  /* Submit form */
  const onSubmitHandler = () => {

    let Elms = [];
    let sElements = selectedElementList;
    sElements.map((elm) =>{
      let item = {};
      item["ElmId"] = elm.ElmId;
      item["Hdr"] = getValues('HDR_' + elm.ElmId);
      item["Ord"] = getValues('ORD_' + elm.ElmId);

      elm.Hdr = item["Hdr"];
      elm.Ord = item["Ord"];

      Elms.push(item);
    });

    setSelectedElementList(sElements);

    let frmData = {
      cmbScrId: ScrId,
      Elms:Elms
    };

    console.log(frmData);

    callServer(frmData, "Upd Task Elements", apiendpoints.UpdTaskElement);

  };


  try {

    return (
      <>
          
              <div className="row">

                <div className="col-md-6">
                  <div className="row" style={{ maxHeight: "500px", overflowY: "auto" }}>
                    <table className="lst-grid">
                      <thead>
                        <tr>
                          <th>&nbsp;</th>
                          <th>Element</th>
                          <th>Heading</th>
                          <th>Ord</th>
                        </tr>
                      </thead>
                      <tbody>
                        <UIElmList elmList={elementList} register={register} />
                      </tbody>
                    </table>
                  </div>
                </div>

                <div className="col-md-6">

                  <div className="row">

                      <div className="col-md-3">
                        <button type="button" className="btn btn-success" onClick={onSubmitHandler}>
                          Submit
                        </button>
                      </div>

                      <div className="col-md-3">
                        <button type="button" className="btn btn-warning" onClick={resetFormData} >
                          Reset
                        </button>
                      </div>

                  </div>

                </div>

              </div>
      </>
    );


  } catch (error) {
    console.log(error.message);
  }

}

export default TaskElements;
